package net.civeira.phylax.feature.access.userwebauthncredential.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.valueobject.AaguidVO;

class AaguidValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of aaguid of user webauthn credential")
  void test_aaguid_value_holder_assign_plain_value() {
    Object holder = new Object();
    AaguidValueHolder<Object> value = new AaguidValueHolder<>(holder);
    Assertions.assertSame(holder, value.aaguid("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAaguidValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getAaguid().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.aaguidNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAaguidValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getAaguid().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of aaguid of user webauthn credential")
  void test_aaguid_value_holder_assign_value_object() {
    Object holder = new Object();
    AaguidValueHolder<Object> value = new AaguidValueHolder<>(holder);
    AaguidVO vo = AaguidVO.from("one");
    Assertions.assertFalse(value.getAaguidValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.aaguid(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAaguidValue().orElseThrow());
    Assertions.assertSame(holder, value.aaguid(Optional.empty()));
    Assertions.assertFalse(value.getAaguidValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.aaguid(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAaguidValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of aaguid of user webauthn credential against the original")
  void test_aaguid_value_holder_read() {
    Object holder = new Object();
    AaguidValueHolder<Object> value = new AaguidValueHolder<>(holder);
    AaguidVO vo = AaguidVO.from("one");
    AaguidVO other = AaguidVO.from("one");
    UserWebauthnCredential original = Mockito.mock(UserWebauthnCredential.class);
    Mockito.when(original.getAaguidValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAaguid(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAaguid(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.aaguid(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAaguid(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAaguid(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of aaguid of user webauthn credential")
  void test_aaguid_value_holder_unset() {
    Object holder = new Object();
    AaguidValueHolder<Object> value = new AaguidValueHolder<>(holder);
    AaguidVO vo = AaguidVO.from("one");
    value.aaguid(vo);
    Assertions.assertSame(holder, value.unsetAaguidIfMatches("aaguid_other"));
    Assertions.assertTrue(value.getAaguidValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAaguidIfMatches("aaguid"));
    Assertions.assertFalse(value.getAaguidValue().isPresent(),
        "The field name must clear the value");
    value.aaguid(vo);
    Assertions.assertSame(holder, value.unsetAaguid());
    Assertions.assertFalse(value.getAaguidValue().isPresent(), "Unset must clear the value");
  }
}
